DROP TABLE IF EXISTS `book`;
CREATE TABLE `book`  (
                         `id` bigint(20) NOT NULL,
                         `book_category_id` bigint(20) NOT NULL COMMENT '分类id',
                         `book_name` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '书名',
                         `author` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '作者',
                         `publication_year` varchar(10) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '出版年份',
                         `isbn` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'isbn',
                         `price` decimal(10, 2) NULL DEFAULT NULL COMMENT '价格',
                         `pages` int(11) NULL DEFAULT NULL COMMENT '页数',
                         `image` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '封面',
                         `stock` int(11) NULL DEFAULT NULL COMMENT '库存',
                         `deleted` tinyint(4) NULL DEFAULT 0 COMMENT '0-未删 1-已删',
                         `create_by` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建人',
                         `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
                         `update_by` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL,
                         `update_time` datetime(0) NULL DEFAULT NULL,
                         PRIMARY KEY (`id`) USING BTREE,
                         UNIQUE INDEX `book_id_uindex`(`id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '图书信息' ROW_FORMAT = Dynamic;

